def fix_chunks(values, size):
    """
    Fixes chunks of values in the input list to a list of consecutive chunks.

    Parameters:
    values (list): The list of values to be fixed.
    size (int): The size of each chunk.

    Returns:
    list: A list of consecutive chunks.
    """
    if size <= 0:
        raise ValueError('Size must be greater than zero.')
    if size == 1:
        return [values]
    result = []
    current_chunk = []
    for value in values:
        if current_chunk:
            if len(current_chunk) < size:
                current_chunk.append(value)
            else:
                result.append(current_chunk)
                current_chunk = []
        else:
            current_chunk.append(value)
    if current_chunk:
        result.append(current_chunk)
    return result
